INSERT OR REPLACE INTO profile_values (user_id, field_key, value_json, updated_at) VALUES ('user_ben', 'st_workExperiences', '[{"title": "Operations & Data Analyst", "employer": "Closing Day", "city": "Apollo Beach, FL", "startDate": "2026-01", "endDate": "", "description": "Sales pipeline analytics platform for real estate teams (closingday.info). Designed and launched a 52-table SQL sales pipeline dashboard with deal flow tracking, conversion funnels, goal pacing, and net commission forecasting. Defined core KPIs and business logic: stage-by-stage conversion rates, win-probability weighting, and a goal engine reverse-engineering income targets into required daily activity. Identified a funnel accuracy problem from backward-moving deals, then redesigned the data structure to preserve full stage-transition history and surface hidden drop-off points. Created a synthetic database replica (3,907 rows, 52 tables) preserving real distributions while eliminating all PII, validated at 0 referential-integrity errors. Translated business requirements into data model specs and validation rules for conversion funnel, lead source ROI, income forecasting, and agent ranking reports."}, {"title": "Operations & Data Analyst", "employer": "The South Shore Team", "city": "Tampa Bay, FL", "startDate": "2016-01", "endDate": "", "description": "Residential real estate, $36 million in annual transaction volume. Founded and run the team, managing the full sales cycle from lead generation through closing. Own the data infrastructure across CRM, MLS, transaction management, and bookkeeping systems powering all reporting, forecasting, and decision-making. Analyzed lead conversion data in Excel and CRM to identify metrics predicting closed deals, then rebuilt KPI reporting to focus effort on highest-probability leads. Reconciled data across 4 systems using Excel and SQL to produce one consistent set of numbers. Built recurring Power BI and Excel reports: agent production, lead conversion, revenue by source, and compliance metrics for leadership and partners. Tracked marketing spend and cost-per-lead in Google Sheets across multiple channels, reallocating budget based on measured ROI per channel."}, {"title": "Police Officer", "employer": "St. Petersburg Police Department", "city": "St. Petersburg, FL", "startDate": "2009", "endDate": "2017", "description": "Sworn service under continuous federal background investigation."}, {"title": "Detention Deputy", "employer": "Hillsborough County Sheriff''s Office", "city": "Tampa, FL", "startDate": "2007", "endDate": "2009", "description": "Ten years of combined sworn service under continuous federal background investigation."}, {"title": "Network Technician", "employer": "Hostway Corp.", "city": "Tampa, FL", "startDate": "2004", "endDate": "2007", "description": "Managed hosting infrastructure support."}, {"title": "Field Technician", "employer": "Bright House Networks", "city": "Tampa, FL", "startDate": "2004", "endDate": "2007", "description": "Field network installation and troubleshooting."}, {"title": "Signal Support Systems Specialist (MOS 25U)", "employer": "United States Army", "city": "", "startDate": "2000", "endDate": "2004", "description": "Maintained LAN servers and 200+ workstations to DoD security standards. Combat deployments supporting Operation Iraqi Freedom and Operation Enduring Freedom. Honorable discharge."}]', '2026-07-28T22:00:00Z');
